void drawBuilding(ra::Engine&e,const Building&b){float x=b.x,y=b.y,z=Tile;if(b.kind==BuildingKind::Base){for(int yy=-2;yy<=2;++yy)for(int xx=-3;xx<=3;++xx)worldTile(e,wooden_,srcCell(0,0,16),x+xx*z,y+yy*z);for(int xx=-3;xx<=3;++xx){worldTile(e,walls_,srcCell(1,0,16),x+xx*z,y-2*z);worldTile(e,walls_,srcCell(1,3,16),x+xx*z,y+2*z);}}else if(b.kind==BuildingKind::Barracks){for(int yy=-1;yy<=1;++yy)for(int xx=-2;xx<=2;++xx)worldTile(e,walls_,srcCell(1+(xx==2),1+(yy==1),16),x+xx*z,y+yy*z);}else if(b.kind==BuildingKind::Hangar){for(int yy=-2;yy<=2;++yy)for(int xx=-2;xx<=2;++xx)worldTile(e,flooring_,srcCell((xx+2)%3,(yy+2)%3,16),x+xx*z,y+yy*z);}else if(b.kind==BuildingKind::Silo){for(int yy=-1;yy<=1;++yy)for(int xx=-1;xx<=1;++xx)worldTile(e,chest_,srcCell(0,0,16),x+xx*z,y+yy*z);}else if(b.kind==BuildingKind::Crop){for(int yy=-1;yy<=1;++yy)for(int xx=-2;xx<=2;++xx){worldTile(e,plains_,srcCell(4,0,16),x+xx*z,y+yy*z);if(b.cropReady)worldTile(e,decor_,srcCell((xx+2)%4,0,16),x+xx*z,y+yy*z);}}else if(b.kind==BuildingKind::Academy){for(int yy=-2;yy<=1;++yy)for(int xx=-2;xx<=2;++xx)worldTile(e,walls_,srcCell((xx+2)%3,(yy+2)%3,16),x+xx*z,y+yy*z);}else if(b.kind==BuildingKind::Training){for(int xx=-3;xx<=3;++xx){worldTile(e,fences_,srcCell(1,1,16),x+xx*z,y-2*z);worldTile(e,fences_,srcCell(1,1,16),x+xx*z,y+2*z);}for(int yy=-1;yy<=1;++yy){worldTile(e,fences_,srcCell(0,1,16),x-3*z,y+yy*z);worldTile(e,fences_,srcCell(0,1,16),x+3*z,y+yy*z);}}float sx=(x-cameraX_)*zoom_,sy=(y-cameraY_)*zoom_;std::string n=buildingName(b.kind);if(b.buildLeft>0)n+=" BUILDING";if(b.kind==BuildingKind::Crop&&b.cropReady)n+=" READY";e.drawText(sx-42,sy-82*zoom_,n,b.team==0?ra::Color{220,240,255,255}:ra::Color{190,230,190,255});if(b.id==selectedBuilding_)e.drawRect({sx-70*zoom_,sy-60*zoom_,140*zoom_,120*zoom_},{255,220,70,255});}
void drawUnits(ra::Engine&e,float vw,float vh){int i=0;for(const auto&u:world_.units()){float x=(u.position.x-cameraX_)*zoom_,y=(u.position.y-cameraY_)*zoom_;UnitKind k=kinds_.count(u.id)?kinds_.at(u.id):UnitKind::Soldier;float s=(k==UnitKind::Air?58:(k==UnitKind::Worker?46:52))*zoom_;if(x<-s||y<-s||x>vw+s||y>vh+s){++i;continue;}if(u.selected)e.drawRect({x-s*.55f,y-s*.55f,s*1.1f,s*1.1f},{255,220,70,255});if(u.team==0)e.drawTextureRegion(player_,frame48((i+(int)u.aiStep)%6,0),{x-s*.5f,y-s*.7f,s,s});else e.drawTextureRegion(slime_,frame32((i+(int)u.aiStep)%4,0),{x-s*.5f,y-s*.5f,s,s});++i;}}
